String Actions::CmdStatus(const String &) { return StatusJson(); }

String Actions::CmdScan(const String &) { return String(I2cBus::Scan()) + " device(s)"; }

String Actions::CmdFlt(const String &) {
  return String("PWR_FLT ") + (turret->board.IsPowerFault() ? "LOW (fault)" : "high (ok)") +
         ", faults since boot: " + String(turret->board.GetPowerFaultCount());
}

String Actions::CmdResetReason(const String &) {
  return String(Board::ResetReasonName(turret->board.GetResetReason())) +
         ", suspicious boots in a row: " + String(turret->board.GetBootLoopCount()) +
         ", brownouts: " + String(turret->board.GetBrownoutCount());
}

String Actions::CmdCrashlog(const String &) {
  const String &previous = CrashLog::PreviousRun();
  return previous.length() ? "---- previous run ----\n" + previous : String("no log from a previous run (power-up)");
}

String Actions::CmdCoredump(const String &args) {
  if (args == "erase") {
    return CoreDump::Erase() ? "core dump erased" : "erase failed";
  }
  return CoreDump::Size() ? "core dump: " + String(CoreDump::Size()) + " bytes, " + CoreDump::Summary() +
                                "\n(download: GET /api/coredump)"
                          : String("no core dump");
}

String Actions::CmdStats(const String &) {
  Stats &stats = turret->stats;
  String last = stats.GetLastCycleAt() ? String((millis() - stats.GetLastCycleAt()) / 1000) + " s ago" : String("none");
  return "boots " + String(stats.GetBoots()) + ", cycles total " + String(stats.GetTotalCycles()) +
         ", since boot: cycles " + String(stats.GetSessionCycles()) + ", targets " +
         String(stats.GetSessionTargets()) + ", last cycle " + last;
}

// ------------------------------------------------------------------ settings

String Actions::CmdGet(const String &args) {
  Settings &settings = turret->settings;
  String out;
  for (int i = 0; i < SettingId::COUNT; i++) {
    const SettingsEntry &entry = settings.entries[i];
    if (args.length() && !args.equalsIgnoreCase(entry.key)) {
      continue;
    }
    out += String(entry.key) + " = ";
    switch (entry.type) {
    case SettingType::Int:
      out += String(entry.value.valueInt);
      if (entry.options != nullptr) {
        char name[SETTING_STRING_MAX];
        if (OptionName(entry.options, entry.value.valueInt, name, sizeof(name))) {
          out += String(" (") + name + ")";
        }
      }
      break;
    case SettingType::Float: out += String(entry.value.valueFloat, 3); break;
    case SettingType::Bool: out += Bool(entry.value.valueBool); break;
    case SettingType::Str:
      out += (i == SettingId::ApPassword || i == SettingId::StaPassword || i == SettingId::WebPassword)
                 ? "********"
                 : entry.value.valueString;
      break;
    }
    out += "\n";
  }
  return out.length() ? out : "unknown key \"" + args + "\"";
}

String Actions::CmdSet(const String &args) {
  String value;
  String key = FirstWord(args, value);
  SettingId id;
  if (key.length() == 0 || !turret->settings.FindId(key.c_str(), id)) {
    return "usage: set <key> <value> (get lists the keys)";
  }
  if (!turret->settings.SetFromString(id, value.c_str())) {
    return "refused: " + key;
  }
  ApplyAllSettings();
  const SettingsEntry *entry = turret->settings.Get(id);
  bool atReboot = strcmp(entry->group, "WiFi") == 0;
  bool homeNetwork = id == SettingId::StaSsid || id == SettingId::StaPassword || id == SettingId::Timezone;
  const char *when = homeNetwork ? "(applied at the next boot, or now with: wifi join)" : "(applied at the next boot)";
  if (id == SettingId::ApPassword || id == SettingId::StaPassword || id == SettingId::WebPassword) {
    return key + " saved " + when;
  }
  return CmdGet(key) + (atReboot ? when : "");
}

String Actions::CmdResetSettings(const String &args) {
  if (args.length() > 0) {
    turret->settings.ResetGroup(args.c_str());
  } else {
    turret->settings.ResetToDefaults();
  }
  ApplyAllSettings();
  return "settings reset" + (args.length() ? " (" + args + ")" : String("")) +
         "; WiFi settings apply at the next boot";
}

String Actions::CmdFactoryReset(const String &) {
  // Same as SW1 closed + PROG held 5 s: everything back to factory state,
  // then a restart (the WiFi settings only apply at boot).
  Log.println("Factory reset: settings, statistics, counters, core dump");
  volumeSavePending = false; // the old volume must not come back at the restart
  turret->settings.ResetToDefaults();
  turret->stats.Clear();
  turret->board.ClearCounters();
  CoreDump::Erase();
  turret->board.ShowFactoryResetAccepted();
  rebootPending = true;
  rebootAt = millis() + FACTORY_RESET_REBOOT_MS;
  return "factory reset done, restarting (access point password: stillalive, web page: Admin / 1234)";
}

// ------------------------------------------------------------------ audio

String Actions::CmdMute(const String &args) {
  bool muted = args == "off" ? false : (args == "on" ? true : !turret->audio.amp.IsMuted());
  turret->audio.amp.SetMuted(muted);
  return muted ? "muted" : "unmuted";
}

String Actions::CmdVolume(const String &args) {
  // Rotary encoder (normal mode) and console: applied at once in RAM, saved
  // in NVS 2 s after the last change (one write for a whole turn of the knob).
  if (args.length() > 0) {
    int32_t value = args.toInt();
    bool relative = args[0] == '+' || args[0] == '-';
    int32_t volume = constrain(relative ? turret->audio.GetVolume() + value : value, 0, 100);
    turret->audio.SetVolume(volume);
    // Turning the volume up while muted: the sound comes back.
    if (relative && value > 0 && turret->audio.amp.IsMuted()) {
      turret->audio.amp.SetMuted(false);
    }
    volumeSavePending = true;
    volumeSaveAt = millis() + VOLUME_SAVE_DELAY_MS;
  }
  return "volume " + String(turret->audio.GetVolume()) + " %" + (turret->audio.amp.IsMuted() ? " (muted)" : "");
}

String Actions::CmdGain(const String &args) {
  // RAM only; use "set AmpGain <dB>" to keep it.
  turret->audio.amp.SetGain(args.toInt());
  return "gain " + String(turret->audio.amp.GetGain()) + " dB (not saved)";
}

String Actions::CmdTone(const String &args) {
  String msText;
  uint32_t hz = FirstWord(args, msText).toInt();
  uint32_t ms = msText.length() ? msText.toInt() : 500;
  if (hz < 20 || hz > 20000 || ms == 0 || ms > 10000) {
    return "usage: tone <20..20000 Hz> [ms <= 10000]";
  }
  turret->audio.PlayTone(hz, ms);
  return "tone " + String(hz) + " Hz, " + String(ms) + " ms";
}

String Actions::CmdShot(const String &) {
  turret->audio.ShootAudio.Begin();
  shotStopAt = millis() + 1000;
  shotPending = true;
  return "gunshot, 1 s";
}

// ------------------------------------------------------------------ network

String Actions::CmdWifi(const String &args) {
  if (args == "on") {
    accessPoint->Start(turret->settings);
    station->Start(turret->settings);
    return "WiFi on";
  }
  if (args == "off") {
    station->Stop();
    accessPoint->Stop();
    return "WiFi off";
  }
  if (args == "scan") {
    station->StartScan();
    return "scanning WiFi networks";
  }
  // Forget the home network (debug menu): the access point stays.
  if (args == "forget") {
    turret->settings.Set(SettingId::StaSsid, "");
    turret->settings.Set(SettingId::StaPassword, "");
    station->Restart(turret->settings);
    return "home network forgotten";
  }
  // First setup: "set StaSsid ...", "set StaPassword ...", then "wifi join" applies them now.
  if (args == "join") {
    station->Restart(turret->settings);
    return station->IsEnabled() ? String("joining \"") + station->GetSsid() + "\""
                                : String("home network disabled (StaSsid empty)");
  }
  String home = !station->IsEnabled() ? String("not configured")
                : station->IsConnected() ? String(station->GetSsid()) + ", " + station->GetIp() + ", " +
                                               String(station->GetRssi()) + " dBm"
                                         : String(station->GetSsid()) + ", not connected";
  return String("access point ") + (accessPoint->IsOn() ? "on" : "off") + ", clients: " +
         String(accessPoint->GetClientCount()) + "; home network: " + home;
}

String Actions::CmdTime(const String &) {
  return Station::HasTime() ? Station::LocalTime() : String("time not set (no NTP yet)");
}

// ------------------------------------------------------------------ system

String Actions::CmdReboot(const String &) {
  rebootPending = true;
  rebootAt = millis() + REBOOT_DELAY_MS;
  return "rebooting";
}

String Actions::CmdResume(const String &) {
  if (stateMachine->GetCurrentStateId() == StateId::Fault) {
    return "refused: power fault";
  }
  turret->light.ClearTest();
  turret->audio.StopTone();
  CancelLabTests();
  // Booting re-homes the mechanics; bench / reduced modes end in Manual again.
  stateMachine->GoToState(StateId::Booting);
  return "resuming (homing, then Idle)";
}

String Actions::CmdDemo(const String &) {
  StateId state = stateMachine->GetCurrentStateId();
  // Debug mode: the state machine is stopped (Manual); a demo cycle is
  // allowed from there once the 3 A supply was declared ("power full").
  bool fromDebug = state == StateId::Manual && turret->board.IsBenchMode();
  if (fromDebug && turret->board.IsServoLimited()) {
    return "refused: one servo at a time (power full first)";
  }
  if (state != StateId::Idle && !fromDebug) {
    return "refused: only from Idle (use resume first)";
  }
  if (!turret->motion.CanDeploy()) {
    return "refused: turret not upright";
  }
  stateMachine->GoToState(StateId::Activate);
  return "demo cycle";
}

String Actions::CmdPower(const String &args) {
  if (args == "full" || args == "limited") {
    turret->board.SetFullPower(args == "full");
  }
  return !turret->board.IsBenchMode() ? String("normal mode: all servos allowed")
         : turret->board.IsServoLimited() ? String("debug mode: one servo at a time (weak supply)")
                                          : String("debug mode: all servos allowed (3 A supply)");
}

String Actions::CmdKey(const String &args) {
  static const struct {
    const char *name;
    logic::MenuKey key;
  } keys[] = {{"a", logic::MenuKey::A},           {"al", logic::MenuKey::ALong},
              {"b", logic::MenuKey::B},           {"bl", logic::MenuKey::BLong},
              {"cw", logic::MenuKey::Clockwise},  {"ccw", logic::MenuKey::Anticlockwise},
              {"push", logic::MenuKey::Push},     {"hold", logic::MenuKey::PushLong}};
  for (const auto &k : keys) {
    if (keyHandler && args == k.name) {
      keyHandler(k.key);
      return "";
    }
  }
  return "usage: key a|al|b|bl|cw|ccw|push|hold (debug menu: A, A long, B, B long;\n"
         "  rotary encoder: clockwise, anticlockwise, push, push held)";
}

String Actions::CmdScreen(const String &) { return screenText ? screenText() : String("no debug screen"); }

String Actions::CmdSelfTest(const String &args) {
  if (selfTest == nullptr) {
    return "self-test not available";
  }
  if (args == "report") {
    return selfTest->HasRun() ? selfTest->Summary(false) + "\n" + selfTest->Report(false)
                              : String("no self-test run yet (selftest | selftest quick)");
  }
  if (args == "stop") {
    selfTest->Stop();
    return "self-test stopped";
  }
  return selfTest->Start(args == "quick", hasDisplay ? hasDisplay() : false);
}

String Actions::CmdSleep(const String &args) {
  return sleep != nullptr ? sleep->Command(args) : String("sleep: not ready");
}

String Actions::SelfTestReport() const {
  if (selfTest == nullptr || !selfTest->HasRun()) {
    return "No self-test run yet.\n";
  }
  return selfTest->Summary(false) + (selfTest->IsRunning() ? "  (running)\n" : "\n") + selfTest->Report(false);
}

String Actions::LoadSnapshot() {
  Gantry &gantry = turret->gantry;
  String text = "servos";
  bool any = false;
  for (uint8_t i = 0; i < Gantry::CHANNEL_COUNT; i++) {
    if (gantry.GetChannel(i).IsAttached()) {
      text += any ? "," : " ";
      text += Gantry::ChannelAlias(i);
      any = true;
    }
  }
  if (!any) {
    text += " none";
  }
  text += String("; sound ") + (turret->audio.IsPlaying() ? "playing" : "silent");
  text += String("; amp ") + (turret->audio.amp.IsRunning() ? "on" : "off");
  text += String("; LEDs ") + (turret->light.IsEnabled() ? "on" : "off");
  text += String("; state ") + StateMachine::StateName(stateMachine->GetCurrentStateId());
  return text;
}

String Actions::MetaJson() const {
  logic::Lang lang = IsFrench() ? logic::Lang::French : logic::Lang::English;
  String json = "{\"lang\":\"";
  json += IsFrench() ? "fr" : "en";
  json += "\",\"faults\":{";
  for (uint8_t n = 1; n <= logic::FAULT_COUNT; n++) {
    json += n > 1 ? ",\"" : "\"";
    json += String(n) + "\":";
    AppendJsonString(json, logic::FaultName(n, lang));
  }
  json += "},\"axes\":[\"off\",\"+X\",\"-X\",\"+Y\",\"-Y\",\"+Z\",\"-Z\"],\"voices\":[";
  for (int i = 0; i < (int)Voice::Count; i++) {
    json += i ? "," : "";
    AppendJsonString(json, Audio::VoiceName((Voice)i));
  }
  json += "],\"servos\":[";
  for (uint8_t i = 0; i < Gantry::CHANNEL_COUNT; i++) {
    json += i ? ",{\"alias\":" : "{\"alias\":";
    AppendJsonString(json, Gantry::ChannelAlias(i));
    json += ",\"name\":";
    AppendJsonString(json, turret->gantry.GetChannel(i).GetName());
    json += "}";
  }
  json += "],\"board\":";
  AppendJsonString(json, BOARD_NAME);
  json += ",\"version\":";
  AppendJsonString(json, FIRMWARE_VERSION);
  json += "}";
  return json;
}

String Actions::StatusJson() {
  Board &board = turret->board;
  Motion &motion = turret->motion;
  Gantry &gantry = turret->gantry;
  Audio &audio = turret->audio;

  String json;
  json.reserve(1024);
  json += "{\"version\":";
  AppendJsonString(json, FIRMWARE_VERSION);
  json += ",\"built\":";
  AppendJsonString(json, __DATE__ " " __TIME__);
  json += ",\"uptimeMs\":" + String(millis());
  json += ",\"state\":";
  AppendJsonString(json, StateMachine::StateName(stateMachine->GetCurrentStateId()));
  json += ",\"resetReason\":";
  AppendJsonString(json, Board::ResetReasonName(board.GetResetReason()));
  json += ",\"bootLoopCount\":" + String(board.GetBootLoopCount());
  json += ",\"brownouts\":" + String(board.GetBrownoutCount());
  json += ",\"powerFaults\":" + String(board.GetPowerFaultCount());
  json += String(",\"pwrFlt\":") + Bool(board.IsPowerFault());
  json += String(",\"benchMode\":") + Bool(board.IsBenchMode());
  json += String(",\"reducedMode\":") + Bool(board.IsReducedMode());
  json += ",\"faults\":[";
  bool first = true;
  for (uint8_t n = 1; n <= 6; n++) {
    if (board.GetFaults() & (1u << (n - 1))) {
      json += first ? "" : ",";
      json += String(n);
      first = false;
    }
  }
  json += "]";
  // bytes / frames / badFrames: fault 4 diagnosis (bytes without frames = wrong baud rate or protocol).
  json += String(",\"radar\":{\"alive\":") + Bool(turret->radar.IsAlive(RADAR_ALIVE_MS)) +
          ",\"targets\":" + String(turret->radar.GetTargetCount()) + ",\"bytes\":" +
          String(turret->radar.GetByteCount()) + ",\"frames\":" + String(turret->radar.GetFrameCount()) +
          ",\"badFrames\":" + String(turret->radar.GetBadFrameCount()) + "}";
  const sensors_vec_t &g = motion.GetAcceleration();
  json += String(",\"imu\":{\"available\":") + Bool(motion.IsAvailable()) + ",\"gravity\":[" +
          String(g.x, 2) + "," + String(g.y, 2) + "," + String(g.z, 2) + "]" +
          ",\"dominantAxis\":" + String(motion.DominantAxis()) + ",\"upright\":" + Bool(motion.IsUpright()) +
          ",\"temperature\":" + String(motion.GetTemperature(), 1) + "}";
  json += ",\"hall\":{\"left\":" + String(gantry.GetWingLeft().GetLastHall()) +
          ",\"right\":" + String(gantry.GetWingRight().GetLastHall()) +
          ",\"fault\":" + Bool(gantry.HasHallFault()) + ",\"powered\":" + Bool(Power::IsOn(Rail::Hall)) + "}";
  json += String(",\"wings\":{\"leftOpen\":") + Bool(gantry.GetWingLeft().IsOpen()) +
          ",\"rightOpen\":" + Bool(gantry.GetWingRight().IsOpen()) +
          ",\"moving\":" + Bool(gantry.GetWingLeft().IsMoving() || gantry.GetWingRight().IsMoving()) + "}";
  json += ",\"servos\":{";
  for (uint8_t i = 0; i < Gantry::CHANNEL_COUNT; i++) {
    ServoChannel &channel = gantry.GetChannel(i);
    json += i ? "," : "";
    AppendJsonString(json, Gantry::ChannelAlias(i));
    json += ":" + (channel.IsAttached() ? String(channel.GetMicroseconds()) : String("null"));
  }
  json += "}";
  json += ",\"amp\":{\"gainDb\":" + String(audio.amp.GetGain()) + ",\"running\":" + Bool(audio.amp.IsRunning()) +
          ",\"muted\":" + Bool(audio.amp.IsMuted()) + "}";
  json += String(",\"wifi\":{\"on\":") + Bool(accessPoint->IsOn()) + ",\"ssid\":";
  AppendJsonString(json, accessPoint->GetSsid());
  json += ",\"clients\":" + String(accessPoint->GetClientCount()) +
          ",\"defaultPassword\":" + Bool(accessPoint->HasDefaultPassword());
  json += String(",\"sta\":{\"enabled\":") + Bool(station->IsEnabled()) +
          ",\"connected\":" + Bool(station->IsConnected()) + ",\"ssid\":";
  AppendJsonString(json, station->GetSsid());
  json += ",\"ip\":";
  AppendJsonString(json, station->GetIp());
  json += ",\"rssi\":" + String(station->GetRssi()) + "}}";
  json += ",\"time\":";
  AppendJsonString(json, Station::LocalTime().c_str());
  json += String(",\"crash\":{\"previousLog\":") + Bool(CrashLog::PreviousRun().length() > 0) +
          ",\"coredump\":" + String(CoreDump::Size()) + ",\"summary\":";
  AppendJsonString(json, CoreDump::Summary().c_str());
  json += "}";
  if (sleep != nullptr) {
    json += ",\"sleep\":" + sleep->StatusJson();
  }
  Stats &stats = turret->stats;
  json += ",\"stats\":{\"boots\":" + String(stats.GetBoots()) + ",\"cycles\":" + String(stats.GetTotalCycles()) +
          ",\"sessionCycles\":" + String(stats.GetSessionCycles()) + ",\"sessionTargets\":" +
          String(stats.GetSessionTargets()) + ",\"lastCycleAgoS\":" +
          (stats.GetLastCycleAt() ? String((millis() - stats.GetLastCycleAt()) / 1000) : String("null")) + "}";
  json += ",\"selfTest\":{\"run\":" + String(Bool(selfTest != nullptr && selfTest->HasRun())) +
          ",\"running\":" + Bool(selfTest != nullptr && selfTest->IsRunning()) + ",\"summary\":";
  AppendJsonString(json, selfTest != nullptr && selfTest->HasRun() ? selfTest->Summary(false).c_str() : "");
  json += "}";
  json += ",\"freeHeap\":" + String(ESP.getFreeHeap());
  json += "}";
  return json;
}
